SELECT jsonb_build_object(
 'role',(SELECT jsonb_build_object('name',r.rolname,'login',r.rolcanlogin,'superuser',r.rolsuper,'inherit',r.rolinherit,'createRole',r.rolcreaterole,'createDb',r.rolcreatedb,'replication',r.rolreplication,'bypassRls',r.rolbypassrls,'connectionLimit',r.rolconnlimit,'marker',shobj_description(r.oid,'pg_authid')) FROM pg_roles r WHERE r.rolname='ca_record_gateway'),
 'memberships',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',target.rolname,'member',member.rolname,'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option,'memberSuperuser',member.rolsuper,'memberCreateRole',member.rolcreaterole)),'[]'::jsonb) FROM pg_auth_members m JOIN pg_roles target ON target.oid=m.roleid JOIN pg_roles member ON member.oid=m.member WHERE target.rolname='ca_record_gateway' OR member.rolname='ca_record_gateway'),
 'ownedObjects',(SELECT count(*) FROM pg_shdepend d JOIN pg_roles r ON r.rolname='ca_record_gateway' WHERE d.refclassid='pg_authid'::regclass AND d.refobjid=r.oid AND d.deptype='o'),
 'canConnect',has_database_privilege('ca_record_gateway',current_database(),'CONNECT'),
 'canCreateDatabaseObjects',has_database_privilege('ca_record_gateway',current_database(),'CREATE'),
 'writableRelations',(SELECT coalesce(jsonb_agg(n.nspname||'.'||c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema' AND c.relkind IN ('r','p','v','m','f') AND (has_table_privilege('ca_record_gateway',c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER,REFERENCES') OR has_any_column_privilege('ca_record_gateway',c.oid,'INSERT,UPDATE,REFERENCES'))),
 'creatableSchemas',(SELECT coalesce(jsonb_agg(n.nspname),'[]'::jsonb) FROM pg_namespace n WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema' AND has_schema_privilege('ca_record_gateway',n.oid,'CREATE')),
 'executableDefiners',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||p.proname,'hash',md5(pg_get_functiondef(p.oid)))),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT LIKE 'pg_%' AND n.nspname<>'information_schema' AND p.prosecdef AND has_schema_privilege('ca_record_gateway',n.oid,'USAGE') AND has_function_privilege('ca_record_gateway',p.oid,'EXECUTE'))
) AS admission;
